preConditionHook:
// THE CHANNEL, built from four confirmed swing pivots and two trend lines.
// One construction is used by every rule in this family so they all draw the
// same channel:
//   * the BULL channel's trend line runs through the two most recent confirmed
//     swing LOWS and its channel line through the two most recent confirmed
//     swing HIGHS;
//   * the BEAR channel is the mirror -- trend line across the HIGHS, channel
//     line across the LOWS.
// The two lines are NOT parallel by construction, which is what lets the
// channel converge (a wedge) or diverge; Brooks draws both forms.
//
// The pivot scan is INLINED here rather than reaching into SwingHigh.json --
// rules in this corpus never reference each other -- and mirrors the EL twin's
// SwingLow / SwingLowBar / SwingHigh / SwingHighBar at Occurrence 1 and 2.
//
// MEASURED, EL_Swing_Probe.txt / el_swing_output1.txt (@ES 60 min):
//   * the pivot test is MIXED -- AT OR ABOVE the pivotStrength older bars,
//     STRICTLY ABOVE the pivotStrength newer bars -- so a flat top yields
//     exactly one pivot, the later of the equal bars;
//   * the confirmation lag is exactly pivotStrength bars, never 0 or 1, which
//     is what makes the scan lookahead-safe;
//   * pivotLookback is EL's Length: candidate offsets 0..pivotLookback-1 from
//     the current bar inclusive, and the neighbourhood test reaches
//     pivotStrength bars PAST the window, so the deepest index touched is
//     pivotLookback - 1 + pivotStrength;
//   * a window with no pivot returns the -1 SENTINEL. Scanning newest-first
//     and taking the first two hits reproduces Occurrence 1 and 2; finding
//     fewer than two is the sentinel case, guarded below. Occurrence 3+ is
//     UNMEASURED and is never asked for;
//   * the comparisons carry the 2.22e-12 relational tolerance, hence el_gt /
//     el_ge inside the scan rather than raw > and >=.
// The low side's tie sense is the mirror of the measured high-side rule. There
// is no WFSafe_SwingHigh, so plain EL governs.
//
// MEASURED, EL_TLValue_Probe.txt: TLValue(P1, B1, P2, B2, target) is the pure
// two-point line Slope = (P2 - P1) / (B2 - B1); value = P1 + (target - B1) *
// Slope, anchored at the FIRST pair and extrapolating freely past both
// anchors. The bar-number convention is the CALLER's; bars-ago is used here,
// so the OLDER pivot (the LARGER bars-ago) is passed as P1/B1 -- the corpus's
// older-anchor-first spelling, measured at zero drift. Bar1 = Bar2 does NOT
// halt, it silently returns 0.0, so the twins guard B1 != B2 instead of
// relying on that. The slope is hoisted out of the per-target arithmetic here
// where the EL twin recomputes it inside each TLValue call: the inputs are
// identical doubles, so the two are bit-for-bit the same line.
//
// THIS RULE: the vacuum test. A LARGE with-trend trend bar reaches the
// projected channel line, and Brooks fades it -- the eager traders who created
// it are the last ones. So THE SIDES READ BACKWARDS FROM THE BAR'S OWN COLOUR,
// deliberately: the LONG side wants a large BEAR trend bar whose low reaches
// the lower channel line, the SHORT side a large bull trend bar whose high
// reaches the upper one. The rule is the trade, not the bar.
//
// Deliberately NOT merged into ChannelLineOvershootReversal, which also fades
// at the line: that bar closes back INSIDE the channel against the trend, this
// one closes with the trend and near its extreme. Opposite bar shapes, and
// they never fire on the same bar.
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration
// is a redefinition when this rule is placed twice in one strategy.
// Every one is fully assigned each bar before it is read.
pivS = (int)pivotStrength;
pivW = (int)pivotLookback;
loP1 = -1.0;
loB1 = -1.0;
loP2 = -1.0;
loB2 = -1.0;
foundLo = 0;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool ok = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_lt(low[j], low[k])) { ok = false; break; }
    }
    if (ok) {
        for (int k = j + 1; k <= j + pivS; ++k) {
            if (!el_le(low[j], low[k])) { ok = false; break; }
        }
    }
    if (ok) {
        ++foundLo;
        if (foundLo == 1) { loP2 = low[j]; loB2 = (double)j; }
        else { loP1 = low[j]; loB1 = (double)j; break; }
    }
}
hiP1 = -1.0;
hiB1 = -1.0;
hiP2 = -1.0;
hiB2 = -1.0;
foundHi = 0;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool ok = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_gt(high[j], high[k])) { ok = false; break; }
    }
    if (ok) {
        for (int k = j + 1; k <= j + pivS; ++k) {
            if (!el_ge(high[j], high[k])) { ok = false; break; }
        }
    }
    if (ok) {
        ++foundHi;
        if (foundHi == 1) { hiP2 = high[j]; hiB2 = (double)j; }
        else { hiP1 = high[j]; hiB1 = (double)j; break; }
    }
}
haveLoLine = (foundLo == 2) && (loB1 != loB2);
haveHiLine = (foundHi == 2) && (hiB1 != hiB2);
loSlope = 0.0;
hiSlope = 0.0;
loNow = 0.0;
hiNow = 0.0;
if (haveLoLine) {
    loSlope = (loP2 - loP1) / (loB2 - loB1);
    loNow = loP1 + (0.0 - loB1) * loSlope;
}
if (haveHiLine) {
    hiSlope = (hiP2 - hiP1) / (hiB2 - hiB1);
    hiNow = hiP1 + (0.0 - hiB1) * hiSlope;
}
// WFSafe_AvgTrueRange: MultiWalk's ROLLING accumulator, ported from
// AtrProfitTarget (the reference, with the measurements). Seeded with a full
// sum on the first calculated bar or when the length changes, and updated
// thereafter as TWO statements -- EL evaluates S[1] + in - out left to right,
// and folding it to S += in - out rounds differently.
// The local counter is atrLen, not atrLength: atrLength is this rule's INPUT.
if (atrLen != (int)atrLength) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLength; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLen = (int)atrLength;
} else {
    const int out = (int)atrLength;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atrVal = atrSum / (int)atrLength;
